seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
stops={"TAA","TAG","TGA"}
def orfs(s, minlen=90):
    out=[]
    for strand,st in [("+",s),("-",rc(s))]:
        for frame in range(3):
            i=frame
            while i<=len(st)-3:
                codon=st[i:i+3]
                if codon=="ATG":
                    # scan to stop
                    j=i
                    while j+3<=len(st):
                        c=st[j:j+3]
                        if c in stops:
                            if j+3-i>=minlen:
                                out.append((strand,frame+1,i+1,j+3,j+3-i,st[i:j+3]))
                            break
                        j+=3
                    i+=3
                else:
                    i+=3
    return out
o=orfs(seq)
o.sort(key=lambda x:-x[4])
for strand,frame,start,end,ln,c in o[:15]:
